import com.lucasalfare.flmidi.Midi
import com.lucasalfare.flmidi.MidiReader
import com.lucasalfare.flmidi.MidiWriter
import org.junit.jupiter.api.BeforeEach
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.Assertions.*

/**
 * Tests for [MidiWriter].
 *
 * These tests validate the binary serialization of [Midi] objects into
 * Standard MIDI File data.
 *
 * The test suite covers three complementary aspects of serialization:
 *
 * - Binary compatibility: the generated bytes must exactly match known
 *   MIDI binary fixtures.
 * - Structural round-tripping: writing and reading a MIDI file must
 *   preserve the resulting [Midi] object.
 * - Encoding behavior: optional features such as running status must
 *   produce valid MIDI data while affecting the binary representation
 *   as expected.
 *
 * The official binary fixtures from [OfficialMidiExamples] are first
 * parsed with [MidiReader]. This provides [Midi] objects that can then
 * be serialized by [MidiWriter] and compared against the original
 * byte sequences.
 */
class MidiWriterTests {

  /**
   * MIDI Format 0 fixture loaded from [OfficialMidiExamples.format0].
   *
   * This object is used as the source model for Format 0 serialization tests.
   */
  private lateinit var midi0: Midi

  /**
   * MIDI Format 1 fixture loaded from [OfficialMidiExamples.format1].
   *
   * This object is used as the source model for Format 1 serialization tests.
   */
  private lateinit var midi1: Midi

  /**
   * Loads the official MIDI fixtures before each test.
   *
   * The fixtures are parsed from their raw binary representation so that
   * the writer tests can serialize actual [Midi] models and compare the
   * resulting bytes against known MIDI data.
   */
  @BeforeEach
  fun setUp() {
    midi0 = MidiReader.fromBytes(OfficialMidiExamples.format0)
    midi1 = MidiReader.fromBytes(OfficialMidiExamples.format1)
  }

  /**
   * Verifies that Format 0 serialization reproduces the official binary
   * fixture byte-for-byte.
   *
   * Running status is enabled because the official fixture contains events
   * encoded using running status.
   *
   * A byte-for-byte comparison is stricter than checking whether the
   * resulting MIDI file can be read successfully: it verifies the exact
   * binary representation produced by [MidiWriter].
   */
  @Test
  fun `writer reproduces official format 0 without differences`() {
    val actual = MidiWriter.toBytes(
      midi0,
      useRunningStatus = true
    )

    assertByteArraysEqual(
      OfficialMidiExamples.format0,
      actual
    )
  }

  /**
   * Verifies that Format 1 serialization reproduces the official binary
   * fixture byte-for-byte.
   *
   * This test ensures that [MidiWriter] correctly serializes multiple
   * tracks, their chunk headers and lengths, and the events contained
   * in each track.
   */
  @Test
  fun `writer reproduces official format 1 without differences`() {
    val actual = MidiWriter.toBytes(
      midi1,
      useRunningStatus = true
    )

    assertByteArraysEqual(
      OfficialMidiExamples.format1,
      actual
    )
  }

  /**
   * Verifies structural equality after a Format 0 write/read round trip.
   *
   * The MIDI object is serialized to bytes and then parsed again by
   * [MidiReader]. The resulting object must be equal to the original.
   *
   * This test does not require the generated bytes to be identical to
   * the original fixture. Instead, it verifies that the information
   * represented by the [Midi] model survives serialization and parsing.
   */
  @Test
  fun `format 0 round trip preserves structural equality`() {
    val written = MidiWriter.toBytes(
      midi0,
      useRunningStatus = true
    )

    val readBack = MidiReader.fromBytes(written)

    assertEquals(midi0, readBack)
  }

  /**
   * Verifies structural equality after a Format 1 write/read round trip.
   *
   * The test ensures that multiple tracks and all supported event data
   * survive serialization and subsequent parsing without changing the
   * resulting [Midi] structure.
   */
  @Test
  fun `format 1 round trip preserves structural equality`() {
    val written = MidiWriter.toBytes(
      midi1,
      useRunningStatus = true
    )

    val readBack = MidiReader.fromBytes(written)

    assertEquals(midi1, readBack)
  }

  /**
   * Verifies that disabling running status still produces valid MIDI data.
   *
   * Running status is an optional binary encoding optimization. When it is
   * disabled, channel-event status bytes are written explicitly instead of
   * being omitted when the same status can be reused.
   *
   * The resulting file must remain completely valid and must decode back
   * into the same [Midi] structure.
   */
  @Test
  fun `without running status still produces readable midi`() {
    val withoutRS = MidiWriter.toBytes(
      midi0,
      useRunningStatus = false
    )

    val readBack = MidiReader.fromBytes(withoutRS)

    assertEquals(midi0, readBack)
  }

  /**
   * Verifies that running status reduces the serialized file size when
   * the input contains consecutive events that can use it.
   *
   * With running status enabled, redundant channel status bytes can be
   * omitted. The resulting representation should therefore contain fewer
   * bytes than the equivalent representation with running status disabled.
   */
  @Test
  fun `running status reduces byte size`() {
    val withRS = MidiWriter.toBytes(
      midi0,
      useRunningStatus = true
    )

    val withoutRS = MidiWriter.toBytes(
      midi0,
      useRunningStatus = false
    )

    assertTrue(
      withRS.size < withoutRS.size,
      "Running status should produce fewer bytes"
    )
  }

  /**
   * Verifies the essential header fields written for a Format 0 file.
   *
   * The test checks:
   *
   * - The `MThd` chunk identifier.
   * - MIDI format 0.
   * - Exactly one track.
   * - A division value of 96 ticks per quarter note.
   *
   * Running status is disabled here because the test is concerned only
   * with the file header.
   */
  @Test
  fun `format 0 header is written correctly`() {
    val bytes = MidiWriter.toBytes(
      midi0,
      useRunningStatus = false
    )

    // "MThd" chunk identifier.
    assertEquals('M'.code.toByte(), bytes[0])
    assertEquals('T'.code.toByte(), bytes[1])
    assertEquals('h'.code.toByte(), bytes[2])
    assertEquals('d'.code.toByte(), bytes[3])

    // Format 0.
    assertEquals(0, bytes[8].toInt())
    assertEquals(0, bytes[9].toInt())

    // Format 0 contains exactly one track.
    assertEquals(0, bytes[10].toInt())
    assertEquals(1, bytes[11].toInt())

    // Division: 96 ticks per quarter note.
    assertEquals(0, bytes[12].toInt())
    assertEquals(96, bytes[13].toInt())
  }

  /**
   * Verifies the essential header fields written for a Format 1 file.
   *
   * The test checks:
   *
   * - The `MThd` chunk identifier.
   * - The number of tracks written to the header.
   * - A division value of 96 ticks per quarter note.
   *
   * Unlike Format 0, Format 1 may contain multiple tracks, so the track
   * count is obtained directly from the [Midi] model.
   */
  @Test
  fun `format 1 header is written correctly`() {
    val bytes = MidiWriter.toBytes(
      midi1,
      useRunningStatus = false
    )

    // "MThd" chunk identifier.
    assertEquals('M'.code.toByte(), bytes[0])
    assertEquals('T'.code.toByte(), bytes[1])
    assertEquals('h'.code.toByte(), bytes[2])
    assertEquals('d'.code.toByte(), bytes[3])

    // Number of tracks.
    assertEquals(0, bytes[10].toInt())
    assertEquals(midi1.tracks.size, bytes[11].toInt())

    // Division: 96 ticks per quarter note.
    assertEquals(0, bytes[12].toInt())
    assertEquals(96, bytes[13].toInt())
  }

  /**
   * Compares two byte arrays element by element.
   *
   * JUnit's standard equality assertion for arrays may not provide the
   * desired byte-by-byte diagnostics. This helper first verifies that
   * both arrays have the same length and then reports the exact index
   * of the first differing byte.
   *
   * This is particularly useful for binary MIDI tests because a single
   * incorrect byte can change the interpretation of the entire sequence
   * that follows it.
   *
   * @param expected expected binary data.
   * @param actual binary data produced by [MidiWriter].
   */
  private fun assertByteArraysEqual(
    expected: ByteArray,
    actual: ByteArray
  ) {
    assertEquals(
      expected.size,
      actual.size,
      "Different byte array sizes"
    )

    for (i in expected.indices) {
      assertEquals(
        expected[i],
        actual[i],
        "Different byte at index $i"
      )
    }
  }
}